using Essco.Domain.HumanResources;namespace Essco.Application.HumanResources;public interface IEmployeeRepository{ValueTask<IReadOnlyCollection<Employee>>ListAsync(string?search,bool includeInactive,CancellationToken token);ValueTask<EmployeeFile?>GetAsync(string identification,CancellationToken token);}public sealed class EmployeeService(IEmployeeRepository repository){public ValueTask<IReadOnlyCollection<Employee>>ListAsync(string?s,bool i,CancellationToken t)=>repository.ListAsync(s?.Trim(),i,t);public ValueTask<EmployeeFile?>GetAsync(string id,CancellationToken t)=>repository.GetAsync(id.Trim(),t);}
